#!/usr/bin/env python3
"""Remove JavaScript and other active XSS vectors from an HTML file.

The file is edited in place.  The sanitizer works on the original source text
(not on a parsed/serialized DOM), so everything that is not removed remains
byte-for-byte identical.
"""

import html as _html
import re
import sys


HTML_WS = " \t\r\n\f"

# Attributes whose value is a URL.
URL_ATTRS = {
    "action",
    "archive",
    "background",
    "cite",
    "classid",
    "code",
    "codebase",
    "data",
    "dynsrc",
    "formaction",
    "href",
    "icon",
    "longdesc",
    "lowsrc",
