def _meta_refresh_is_dangerous(value):
    norm = _url_normalized(value)
    for scheme in DANGEROUS_SCHEMES:
        if scheme in norm:
            return True
    if "data:" in norm:
        at = norm.find("data:")
        rest = norm[at + 5:]
        mime = rest.split(";", 1)[0].split(",", 1)[0].strip()
