    lower = s.lower()
    needle = "</" + name.lower()
    pos = start
    while True:
        at = lower.find(needle, pos)
        if at < 0:
            return None
        after = at + len(needle)
        if after >= len(s) or s[after] in HTML_WS or s[after] in "/>":
