    "image/png",
    "image/tiff",
    "image/vnd.microsoft.icon",
    "image/webp",
    "image/x-icon",
    "audio/aac",
    "audio/flac",
    "audio/mpeg",
    "audio/ogg",
    "audio/wav",
    "audio/webm",
    "video/mp4",
    "video/ogg",
    "video/webm",
    "font/otf",
    "font/ttf",
    "font/woff",
    "font/woff2",
}

_CSS_DANGER = (
    "javascript:",
    "vbscript:",
    "livescript:",
    "expression(",
    "-moz-binding",
    "behavior:",
    "-ms-behavior",
    "-o-link",
    "data:text/html",
    "data:application/xhtml+xml",
    "data:image/svg+xml",
    "data:application/xml",
    "data:text/xml",
    "data:application/javascript",
    "data:text/javascript",
    "data:application/ecmascript",
    "data:text/ecmascript",
)


def _local_name(name):
    """Return the local part of a (possibly namespaced) HTML/XML name."""
    name = name.lower()
    if ":" in name:
        return name.rsplit(":", 1)[1]
    return name


def _is_ascii_alpha(ch):
    return ("a" <= ch <= "z") or ("A" <= ch <= "Z")


def _find_tag_end(s, pos):
    """Find the end (one past '>') of a tag starting at pos."""
    n = len(s)
    i = pos + 1
    quote = None
    while i < n:
        ch = s[i]
        if quote is not None:
            if ch == quote:
                quote = None
        elif ch in "\"'":
            # Quotes are only special as the start of an attribute value.
            # Treating any quote in a tag as opening a quoted run is the same
            # choice made by common HTML lexers and avoids stopping at a '>'
            # that occurs inside an attribute value.
            quote = ch
        elif ch == ">":
            return i + 1
        i += 1
    return n


def _parse_tag(s, pos):
    """Parse a start tag without reserializing it.

    Returns a dict containing the tag end, its name, and exact attribute
    source ranges.  Attribute values are the raw source between quotes;
    the quote characters themselves are not part of the value range.
    """
    n = len(s)
    i = pos + 1
    name_start = i
    while i < n and s[i] not in HTML_WS and s[i] not in "/>":
        i += 1
    name = s[name_start:i]

    attrs = []
    tag_end = n
    while i < n:
        ws_start = i
        while i < n and s[i] in HTML_WS:
            i += 1
        if i >= n:
            tag_end = n
            break
        if s[i] == ">":
            tag_end = i + 1
            break
        if s[i] == "/":
            if i + 1 < n and s[i + 1] == ">":
                tag_end = i + 2
                break
            # A stray slash before an attribute is ignored by HTML parsers.
            i += 1
            continue

        attr_start = ws_start
        attr_name_start = i
        while i < n and s[i] not in HTML_WS and s[i] not in "=/>":
            i += 1
        if i == attr_name_start:
            # Defensive: always make progress on malformed input.
            i += 1
            continue
        attr_name = s[attr_name_start:i]

        # Whitespace after the name is part of the separator before a value.
        j = i
        while j < n and s[j] in HTML_WS:
            j += 1

        value_start = None
        value_end = None
        value_quote = None
        if j < n and s[j] == "=":
            j += 1
            while j < n and s[j] in HTML_WS:
                j += 1
            if j < n and s[j] in "\"'":
                value_quote = s[j]
                value_start = j + 1
                close = s.find(value_quote, value_start)
                if close < 0:
                    close = n
                value_end = close
                i = min(close + 1, n)
            else:
                value_start = j
                k = j
                while k < n and s[k] not in HTML_WS and s[k] != ">":
                    k += 1
                value_end = k
                i = k
        # If there was no "=", i is already at the end of the attribute name;
        # leave the following whitespace for the next attribute.

        attrs.append(
            {
                "start": attr_start,
                "name_start": attr_name_start,
                "name_end": attr_name_start + len(attr_name),
                "name": attr_name,
                "local": _local_name(attr_name),
                "value_start": value_start,
                "value_end": value_end,
                "value_quote": value_quote,
                "end": i,
            }
        )

    return {"start": pos, "end": tag_end, "name": name, "local": _local_name(name), "attrs": attrs}


def _attr_raw(s, attr):
    if attr["value_start"] is None:
        return ""
    return s[attr["value_start"]:attr["value_end"]]


def _decoded_attr(s, attr):
    return _html.unescape(_attr_raw(s, attr))


def _remove_controls_and_space(value):
    out = []
    for ch in value:
        o = ord(ch)
        if o <= 0x20 or 0x7F <= o <= 0x9F:
            continue
        if ch in "\u200b\u200c\u200d\u200e\u200f\u2028\u2029\ufeff":
            continue
        out.append(ch)
    return "".join(out)


def _url_normalized(value):
    # Attribute values are entity-decoded by the HTML parser before use.
    value = _html.unescape(value)
    # Browsers ignore ASCII controls/whitespace in URL schemes, and old
    # browsers were even more forgiving.  Removing them also defeats the
    # usual java<TAB>script: and java&#x0a;script: bypasses.
    value = _remove_controls_and_space(value)
    # Backslashes are treated as slashes by some URL parsers; dropping them
    # makes the dangerous-scheme check conservative.
    value = value.replace("\\", "")
    value = value.lower()
    # Inline HTML comments are ignored by some legacy URL parsers.
    while "<!--" in value and "-->" in value:
        a = value.find("<!--")
        b = value.find("-->", a + 4)
        if b < 0:
            break
        value = value[:a] + value[b + 3:]
    return value


def _data_url_is_safe(normalized, attr_name):
    if not normalized.startswith("data:"):
        return True
    rest = normalized[5:]
    mime = rest.split(";", 1)[0].split(",", 1)[0]
    mime = mime.strip()
    if mime in SAFE_DATA_MIME_TYPES:
        return True
    # Data URLs without an explicit media type are text/plain, but browsers
    # and old filters disagree about sniffing them; reject them.
    return False


def _url_is_dangerous(value, attr_name):
    norm = _url_normalized(value)
    for scheme in DANGEROUS_SCHEMES:
        if norm.startswith(scheme):
            return True
    if norm.startswith("data:") and not _data_url_is_safe(norm, attr_name):
        return True
    return False


def _srcset_is_dangerous(value):
    norm = _url_normalized(value)
    for scheme in DANGEROUS_SCHEMES:
        if scheme in norm:
            return True
    # Check data URLs in the set, including those with commas in their payload.
    pos = 0
    while True:
        at = norm.find("data:", pos)
        if at < 0:
            break
        rest = norm[at + 5:]
        mime = rest.split(";", 1)[0].split(",", 1)[0].strip()
        if mime not in SAFE_DATA_MIME_TYPES:
            return True
        comma = rest.find(",")
        if comma < 0:
            break
        pos = at + 5 + comma + 1
    return False


def _meta_refresh_is_dangerous(value):
    norm = _url_normalized(value)
    for scheme in DANGEROUS_SCHEMES:
        if scheme in norm:
            return True
    if "data:" in norm:
        at = norm.find("data:")
        rest = norm[at + 5:]
        mime = rest.split(";", 1)[0].split(",", 1)[0].strip()
        if mime not in SAFE_DATA_MIME_TYPES:
            return True
    return False


def _decode_css_escapes(value):
    """Decode CSS backslash escapes (used to hide java\\73cript:, etc.)."""
    out = []
    i = 0
    n = len(value)
    while i < n:
        ch = value[i]
        if ch != "\\":
            out.append(ch)
            i += 1
            continue
        i += 1
        if i >= n:
            break
        if value[i] in "\r\n\f":
            # Escaped newline: a line continuation.
            if value[i] == "\r" and i + 1 < n and value[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue
        if value[i] in "0123456789abcdefABCDEF":
            j = i
            while j < n and j < i + 6 and value[j] in "0123456789abcdefABCDEF":
                j += 1
            try:
                cp = int(value[i:j], 16)
                if cp == 0 or cp > 0x10FFFF or 0xD800 <= cp <= 0xDFFF:
                    cp = 0xFFFD
                out.append(chr(cp))
            except ValueError:
                pass
            i = j
            # One whitespace character after a hex escape is consumed.
            if i < n and value[i] in " \t\r\n\f":
                if value[i] == "\r" and i + 1 < n and value[i + 1] == "\n":
                    i += 2
                else:
                    i += 1
            continue
        out.append(value[i])
        i += 1
    return "".join(out)


def _remove_css_comments(value):
    out = []
    i = 0
    n = len(value)
    while i < n:
        if value.startswith("/*", i):
            end = value.find("*/", i + 2)
            if end < 0:
                break
            i = end + 2
            continue
        out.append(value[i])
        i += 1
    return "".join(out)


def _css_normalized(value):
    value = _html.unescape(value)
    value = _decode_css_escapes(value)
    value = _remove_css_comments(value)
    value = _remove_controls_and_space(value)
    return value.lower()


def _css_is_dangerous(value):
    norm = _css_normalized(value)
    return any(needle in norm for needle in _CSS_DANGER)


def _find_css_segments(css):
    """Yield (start, end, terminator_index, terminator_char) for CSS pieces.

    Semicolons and braces outside strings, comments and parentheses delimit
    declarations/rules.  This lets us delete one dangerous declaration while
    keeping the rest of a stylesheet untouched.
    """
    n = len(css)
    i = 0
    seg_start = 0
    paren = 0
    while i < n:
        ch = css[i]
        if ch == "/" and i + 1 < n and css[i + 1] == "*":
            end = css.find("*/", i + 2)
            i = n if end < 0 else end + 2
            continue
        if ch in "\"'":
            quote = ch
            i += 1
            while i < n:
                if css[i] == "\\":
                    i += 2
                elif css[i] == quote:
                    i += 1
                    break
                else:
                    i += 1
            continue
        if ch == "\\":
            i += 2
            continue
        if ch == "(":
            paren += 1
        elif ch == ")" and paren:
            paren -= 1
        elif paren == 0 and ch in ";{}":
            if ch in ";}":
                yield (seg_start, i, i, ch)
            else:
                # Selector/prelude before '{' is not executable.
                pass
            seg_start = i + 1
        i += 1
    yield (seg_start, n, n, "")


def _sanitize_css(css):
    if not css:
        return css
    out = []
    cursor = 0
    for start, end, term, term_ch in _find_css_segments(css):
        if _css_is_dangerous(css[start:end]):
            out.append(css[cursor:start])
            cursor = term + 1 if term_ch == ";" else term
    out.append(css[cursor:])
    result = "".join(out)
    # If something dangerous survived (for example a selector prelude that
    # our declaration splitter intentionally did not remove), empty the CSS
    # rather than risk emitting it.
    if _css_is_dangerous(result):
        return ""
    return result


def _find_raw_close(s, start, name):
    """Find a matching end tag in RAWTEXT/RCDATA content.

    Returns (tag_start, tag_end) or None.  The delimiter rule matches the
    HTML tokenizer: </name must be followed by whitespace, '/', '>', or EOF.
    """
    lower = s.lower()
    needle = "</" + name.lower()
    pos = start
    while True:
        at = lower.find(needle, pos)
        if at < 0:
            return None
        after = at + len(needle)
        if after >= len(s) or s[after] in HTML_WS or s[after] in "/>":
            gt = s.find(">", after)
            if gt < 0:
                return (at, len(s))
            return (at, gt + 1)
        pos = at + 1


def _comment_end(s, start):
    """Return the end offset of an HTML comment beginning at start."""
    n = len(s)
    if s.startswith("<!-->", start):
        return start + 5
    if s.startswith("<!--->", start):
        return start + 6
    a = s.find("-->", start + 4)
    b = s.find("--!>", start + 4)
    ends = [x for x in (a, b) if x >= 0]
    if not ends:
        return n
    at = min(ends)
    return at + (4 if at == b and (a < 0 or b < a) else 3)


def _find_declaration_end(s, start):
    """Find '>' for a doctype/declaration, honoring quoted public ids."""
    n = len(s)
    i = start + 2
    quote = None
    while i < n:
        ch = s[i]
        if quote:
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
        elif ch == ">":
            return i + 1
        i += 1
    return n


def _sanitize_start_tag(s, parsed):
    """Return the start tag with dangerous attributes removed."""
    tag_local = parsed["local"]
    attrs = parsed["attrs"]

    meta_refresh = False
    if tag_local == "meta":
        for attr in attrs:
            if attr["local"] == "http-equiv":
                if _remove_controls_and_space(_decoded_attr(s, attr)).lower() == "refresh":
                    meta_refresh = True
                    break

    animation_target = None
    if tag_local in ANIMATION_ELEMENTS:
        for attr in attrs:
            if attr["local"] == "attributename":
                animation_target = _remove_controls_and_space(
                    _decoded_attr(s, attr)
                ).lower()
                if ":" in animation_target:
                    animation_target = animation_target.rsplit(":", 1)[1]
                break

    out = []
    cursor = parsed["start"]
    for attr in attrs:
        name_local = attr["local"]
        raw_value = _attr_raw(s, attr)
        action = "keep"
        replacement = None

        # Any on* attribute is an event handler, including namespaced ones.
        if name_local.startswith("on"):
            action = "remove"

        elif name_local == "srcdoc":
            # srcdoc is parsed as a document and can contain arbitrary script.
            action = "remove"

        elif name_local in URL_ATTRS:
            if _url_is_dangerous(raw_value, name_local):
                action = "remove"

        elif name_local in SRCSET_ATTRS:
            if _srcset_is_dangerous(raw_value):
                action = "remove"

        elif name_local == "style":
            new_css = _sanitize_css(raw_value)
            if new_css != raw_value:
                if not new_css.strip() or attr["value_quote"] is None:
                    action = "remove"
                else:
                    action = "replace"
                    replacement = new_css

        elif name_local in CSS_VALUE_ATTRS:
            if _css_is_dangerous(raw_value):
                action = "remove"

        elif meta_refresh and name_local == "content":
            if _meta_refresh_is_dangerous(raw_value):
                action = "remove"

        elif tag_local in ANIMATION_ELEMENTS and animation_target is not None:
            if animation_target.startswith("on"):
                # Animating an event handler attribute is script execution.
                if name_local == "attributename" or name_local in ANIMATION_VALUE_ATTRS:
                    action = "remove"
            elif (
                animation_target in URL_ATTRS
                or animation_target in SRCSET_ATTRS
                or animation_target == "style"
                or animation_target in CSS_VALUE_ATTRS
            ) and name_local in ANIMATION_VALUE_ATTRS:
                if (
                    _url_is_dangerous(raw_value, animation_target)
                    or _srcset_is_dangerous(raw_value)
                    or _css_is_dangerous(raw_value)
                ):
                    action = "remove"

        if action == "remove":
            out.append(s[cursor:attr["start"]])
            cursor = attr["end"]
        elif action == "replace":
            out.append(s[cursor:attr["value_start"]])
            out.append(replacement)
            cursor = attr["value_end"]

    out.append(s[cursor:parsed["end"]])
    return "".join(out)


def filter_html(s):
    """Return s with JavaScript and JavaScript-capable content removed."""
    out = []
    i = 0
    n = len(s)

    while i < n:
        lt = s.find("<", i)
        if lt < 0:
            out.append(s[i:])
            break
        out.append(s[i:lt])

        # Comment.  Conditional comments execute in old IE, so drop them.
        if s.startswith("<!--", lt):
            end = _comment_end(s, lt)
            comment = s[lt:end]
            if re.match(r"<!--\s*\[if\b", comment, re.IGNORECASE):
                pass
            else:
                out.append(comment)
            i = end
            continue

        # CDATA section (treated as text in HTML, script-safe in foreign
        # content).  Keep it verbatim.
        if s.startswith("<![CDATA[", lt):
            end = s.find("]]>", lt + 9)
            end = n if end < 0 else end + 3
            out.append(s[lt:end])
            i = end
            continue

        lower_tail = s[lt:lt + 9].lower()
        if lower_tail.startswith("<!doctype"):
            end = _find_declaration_end(s, lt)
            out.append(s[lt:end])
            i = end
            continue

        # Bogus comments/declarations end at the first '>'.
        if s.startswith("<!", lt) or s.startswith("<?", lt):
            end = s.find(">", lt + 2)
            end = n if end < 0 else end + 1
            out.append(s[lt:end])
            i = end
            continue

        # End tags are inert.  Copy them through their '>'; script end tags
        # belonging to a removed script are consumed below.
        if s.startswith("</", lt):
            if lt + 2 < n and _is_ascii_alpha(s[lt + 2]):
                end = s.find(">", lt + 2)
                end = n if end < 0 else end + 1
                out.append(s[lt:end])
                i = end
                continue
            out.append("<")
            i = lt + 1
            continue

        # Start tag.
        if lt + 1 < n and _is_ascii_alpha(s[lt + 1]):
            parsed = _parse_tag(s, lt)
            tag_local = parsed["local"]
            tag_end = parsed["end"]

            if tag_local == "script":
                close = _find_raw_close(s, tag_end, parsed["name"])
                i = close[1] if close else n
                continue

            if tag_local in PLAINTEXT_ELEMENTS:
                out.append(_sanitize_start_tag(s, parsed))
                out.append(s[tag_end:])
                break

            if tag_local == "style":
                out.append(_sanitize_start_tag(s, parsed))
                close = _find_raw_close(s, tag_end, parsed["name"])
                if close is None:
                    out.append(_sanitize_css(s[tag_end:]))
                    i = n
                else:
                    out.append(_sanitize_css(s[tag_end:close[0]]))
                    out.append(s[close[0]:close[1]])
                    i = close[1]
                continue

            if tag_local in RCDATA_ELEMENTS or tag_local in RAWTEXT_PRESERVE_ELEMENTS:
                out.append(_sanitize_start_tag(s, parsed))
                close = _find_raw_close(s, tag_end, parsed["name"])
                if close is None:
                    out.append(s[tag_end:])
                    i = n
                else:
                    out.append(s[tag_end:close[0]])
                    out.append(s[close[0]:close[1]])
                    i = close[1]
                continue

            if tag_local in RAWTEXT_SCRUB_ELEMENTS:
                out.append(_sanitize_start_tag(s, parsed))
                close = _find_raw_close(s, tag_end, parsed["name"])
                if close is None:
                    out.append(filter_html(s[tag_end:]))
                    i = n
                else:
                    out.append(filter_html(s[tag_end:close[0]]))
                    out.append(s[close[0]:close[1]])
                    i = close[1]
                continue

            out.append(_sanitize_start_tag(s, parsed))
            i = tag_end
            continue

        # A literal '<' (for example "1 < 2").
        out.append("<")
        i = lt + 1

    return "".join(out)


def main(argv):
    if len(argv) != 2:
        sys.stderr.write("usage: filter.py <html-file>\n")
        return 2

    path = argv[1]
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except OSError as exc:
        sys.stderr.write("filter.py: %s\n" % exc)
        return 1

    text = data.decode("utf-8", "surrogateescape")
    cleaned = filter_html(text)
    if cleaned != text:
        cleaned_bytes = cleaned.encode("utf-8", "surrogateescape")
        try:
            with open(path, "wb") as fh:
                fh.write(cleaned_bytes)
        except OSError as exc:
            sys.stderr.write("filter.py: %s\n" % exc)
            return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

